def _flatten(obj, prefix, sep, result):
    if isinstance(obj, dict):
        if not obj:
            result[prefix] = obj
        else:
            for key, value in obj.items():
                new_prefix = f"{prefix}{sep}{key}" if prefix else str(key)
                _flatten(value, new_prefix, sep, result)
    elif isinstance(obj, list):
        if not obj:
            result[prefix] = obj
        else:
            for idx, value in enumerate(obj):
                new_prefix = f"{prefix}{sep}{idx}" if prefix else str(idx)
                _flatten(value, new_prefix, sep, result)
    else:
        result[prefix] = obj

def flatten(obj, sep: str = '.') -> dict:
    def _flatten(obj, prefix: str, result: dict):
        if isinstance(obj, dict):
            if not obj:
                result[prefix] = obj if prefix else None
                return
            for key, value in obj.items():
                new_prefix = f"{prefix}{sep}{key}" if prefix else str(key)
                _flatten(value, new_prefix, result)
        elif isinstance(obj, (list, tuple)):
            if not obj:
                result[prefix] = obj if prefix else None
                return
            for idx, value in enumerate(obj):
                new_prefix = f"{prefix}{sep}{idx}" if prefix else str(idx)
                _flatten(value, new_prefix, result)
        else:
            result[prefix] = obj

    result = {}
    _flatten(obj, '', result)
    return result

def compare_versions(v1: str, v2: str) -> int:
    def parse(v: str):
        parts = v.strip().split('.')
        numeric = []
        for p in parts:
            # Strip any non-numeric suffix if present (e.g., beta, rc)
            # But the problem says "comparing dotted version strings numerically"
            # So we just parse numeric parts. If a part is not numeric, we handle it.
            try:
                numeric.append(int(p))
            except ValueError:
                pass  # or raise, but let's assume numeric-only per problem
        return numeric

    a = parse(v1)
    b = parse(v2)

    # Pad the shorter list with zeros
    max_len = max(len(a), len(b))
    a.extend([0] * (max_len - len(a)))
    b.extend([0] * (max_len - len(b)))

    for i in range(max_len):
        if a[i] < b[i]:
            return -1
        elif a[i] > b[i]:
            return 1
    return 0

def compare_versions(v1: str, v2: str) -> int:
