import functools
import typing

def retry(times: int, exceptions: typing.Tuple[type, ...] = (Exception,)):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
                    continue
                except Exception as e:
                    raise
            raise last_exception
        return wrapper
    return decorator

