def ladder_length(begin: str, end: str, words: list[str]) -> int:
    word_set = set(words)
    if end not in word_set:
        return 0

    if begin == end:
        return 1

    L = len(begin)

    # Build adjacency: for each word, find all words that differ by one letter
    # Instead of precomputing everything, do BFS with wildcard matching

    from collections import defaultdict

    # Map pattern -> list of words for fast lookup
    pattern_map = defaultdict(list)
    all_words = word_set | {begin}
    for w in all_words:
        for i in range(L):
            pattern = w[:i] + '*' + w[i+1:]
            pattern_map[pattern].append(w)

    visited = {begin}
    queue = deque([(begin, 1)])

    while queue:
        current, count = queue.popleft()
        if current == end:
            return count
        for i in range(L):
            pattern = current[:i] + '*' + current[i+1:]
            for neighbor in pattern_map[pattern]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, count + 1))

    return 0

from collections import deque

def ladder_length(begin: str, end: str, words: list[str]) -> int:
    word_set = set(words)

    if end not in word_set:
        return 0

    word_len = len(begin)

    # Build adjacency: for each word, possible neighbors by changing one char
    # We'll use BFS from begin

    def get_neighbors(word):
        neighbors = []
        word_list = list(word)
        for i in range(word_len):
            original = word_list[i]
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c != original:
                    word_list[i] = c
                    new_word = ''.join(word_list)
                    if new_word in word_set:
                        neighbors.append(new_word)
            word_list[i] = original
        return neighbors

    if begin == end:
        return 1 if end in word_set else 0

    # BFS
    queue = deque([begin])
    visited = {begin}
    steps = 1

    while queue:
        # Process all nodes at current level
        for _ in range(len(queue)):
            word = queue.popleft()
            for neighbor in get_neighbors(word):
                if neighbor == end:
                    return steps + 1
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        steps += 1

    return 0

def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression string supporting + - * / parentheses,
    unary minus, integers and decimals, with correct precedence.
    Raises ValueError on malformed input.
    """
    expr = expr.strip()
    if not expr:
        raise ValueError("Empty expression")

    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in '+-*/()':
            tokens.append(c)
            i += 1
            continue
        if c.isdigit() or c == '.':
            # Read a number
            j = i
            has_dot = False
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j] == '.':
                    if has_dot:
                        raise ValueError(f"Invalid number near position {i}")
                    has_dot = True
                j += 1
            tokens.append(expr[i:j])
            i = j
            continue
        raise ValueError(f"Unexpected character '{c}' at position {i}")

    # Convert to token list for parser
    # Grammar:
    # expr   -> term (('+' | '-') term)*
    # term   -> factor (('*' | '/') factor)*
    # factor -> ('+' | '-') factor | number | '(' expr ')'

    pos = 0
    tokens_len = len(tokens)

    def parse_expr():
        nonlocal pos
        result = parse_term()
        while pos < tokens_len and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        nonlocal pos
        result = parse_factor()
        while pos < tokens_len and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right = parse_factor()
            if op == '*':
                result *= right
            else:
                if right == 0:
                    raise ValueError("Division by zero")
                result /= right
        return result

    def parse_factor():
        nonlocal pos
        if pos >= tokens_len:
            raise ValueError("Unexpected end of expression")

        token = tokens[pos]

        # Unary plus/minus
        if token == '+':
            pos += 1
            return parse_factor()

        if token == '-':
            pos += 1
            return -parse_factor()

        # Parenthesized expression
        if token == '(':
            pos += 1
            if pos >= tokens_len or tokens[pos] != ')':
                # Parse inner expression
                result = parse_expr()
                if pos >= tokens_len or tokens[pos] != ')':
                    raise ValueError("Missing closing parenthesis")
                pos += 1
                return result
            else:
                pos += 1
                raise ValueError("Empty parentheses")

        # Number
        if token not in '+-*/()':
            try:
                return float(token)
            except ValueError:
                raise ValueError(f"Invalid number '{token}'")

        raise ValueError(f"Unexpected token '{token}'")

    result = parse_expr()

    # Ensure we consumed all tokens
    if pos != tokens_len:
        raise ValueError(f"Unexpected token at position {pos}")

    return result

def evaluate(expr: str) -> float:
    pos = 0
    n = len(expr)

    def peek():
        return expr[pos] if pos < n else None

    def next_char():
        nonlocal pos
        ch = expr[pos] if pos < n else None
        pos += 1
        return ch

    def skip_spaces():
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_expr():
        nonlocal pos
        left = parse_term()
        while True:
            skip_spaces()
            if peek() in ('+', '-'):
                op = next_char()
                right = parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_term():
        nonlocal pos
        left = parse_factor()
        while True:
            skip_spaces()
            if peek() in ('*', '/'):
                op = next_char()
                right = parse_factor()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ValueError("Division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_factor():
        nonlocal pos
        skip_spaces()
        if peek() is None:
            raise ValueError("Unexpected end of expression")
        if peek() == '(':
            next_char()
            val = parse_expr()
            skip_spaces()
            if peek() != ')':
                raise ValueError("Expected closing parenthesis")
            next_char()
            return val
        if peek() == '-':
            next_char()
            return -parse_factor()
        if peek() == '+':
            next_char()
            return parse_factor()
        # Number
        start = pos
        has_dot = False
        while pos < n and (expr[pos].isdigit() or (expr[pos] == '.' and not has_dot)):
            if expr[pos] == '.':
                has_dot = True
            pos += 1
        if pos == start:
            raise ValueError("Expected a number or parenthesis")
        num_str = expr[start:pos]
        try:
            return float(num_str)
        except ValueError:
            raise ValueError(f"Invalid number: {num_str}")

    result = parse_expr()
    skip_spaces()
    if pos != n:
        raise ValueError(f"Unexpected character at position {pos}")
    return result

def diff(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    n, m = len(a), len(b)
    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = dp[i + 1][j + 1] + 1
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    result = []
    i, j = 0, 0
    while i < n and j < m:
        if a[i] == b[j]:
            result.append((' ', a[i]))
            i += 1
            j += 1
        elif dp[i + 1][j] >= dp[i][j + 1]:
            result.append(('-', a[i]))
            i += 1
        else:
            result.append(('+', b[j]))
            j += 1
    while i < n:
        result.append(('-', a[i]))
        i += 1
    while j < m:
        result.append(('+', b[j]))
        j += 1

    return result
